import React from 'react';
import { Link } from 'react-router-dom';

function Navbar({ user, cart, onLogout }) {
    const cartCount = cart.reduce((count, item) => count + item.quantity, 0);

    return (
        <nav className="navbar bg-green-500 p-4 text-white">
            <div className="logo">
                <Link to="/" className="text-white font-bold text-xl">MyShop</Link>
            </div>
            <div className="nav-links flex space-x-4">
                <Link to="/products" className="hover:underline">Products</Link>
                <Link to="/cart" className="hover:underline">Cart ({cartCount})</Link>
                {user ? (
                    <>
                        <Link to="/orders" className="hover:underline">Orders</Link>
                        <span className="user-profile">Hello, {user.name}</span>
                        <button onClick={onLogout} className="bg-red-500 px-3 py-1 rounded hover:bg-red-600">Logout</button>
                    </>
                ) : (
                    <Link to="/login" className="hover:underline">Login</Link>
                )}
            </div>
        </nav>
    );
}

export default Navbar;
